insert into public.training_scenarios_v22(stable_key,title,scenario_type,role_focus,intro,prompt,decisions,debrief,visuals,media,sources) values
('v22:fire-l1','Antincendio L1: principio d’incendio e scelta dell’estintore','decision','addetto antincendio L1','Un cestino prende fuoco in un’area facilmente evacuabile, senza fumo denso e con via di fuga libera.','Decidi allarme, evacuazione, scelta del mezzo, posizione e limite oltre il quale abbandoni il tentativo.','[{"choice":"Allerto, mantengo la via di fuga e intervengo solo sul principio d’incendio controllabile","effect":"Intervento proporzionato"},{"choice":"Mi concentro prima sullo spegnimento e avviso dopo","effect":"Ritardo allarme/esodo"}]'::jsonb,'{"questions":["Quale estintore è adatto?","Dove ti posizioni?","Quale cambiamento ti fa interrompere?"]}'::jsonb,'[{"asset":"idea-fire-triangle.svg"},{"asset":"idea-fire-response.svg"}]'::jsonb,'[{"kind":"reference","title":"Vigili del Fuoco - formazione addetti antincendio","url":"https://www.vigilfuoco.it/comando-vvf-rimini/formazione-abilitazione-e-aggiornamento-addetti-antincendio"}]'::jsonb,'[{"authority":"Corpo Nazionale Vigili del Fuoco","url":"https://www.vigilfuoco.it/comando-vvf-rimini/formazione-abilitazione-e-aggiornamento-addetti-antincendio"}]'::jsonb),
('v22:fire-l2','Antincendio L2: propagazione, compartimento e squadra','tabletop','addetto antincendio L2','Un incendio coinvolge materiale combustibile in un locale e il fumo può raggiungere un corridoio di esodo.','Coordina allarme, chiusure/compartimentazione previste, evacuazione, scelta dei mezzi e comunicazione tra addetti.','[{"choice":"Divido i compiti e proteggo l’esodo prima di aumentare l’impegno nello spegnimento","effect":"Priorità a persone e propagazione"},{"choice":"Concentro tutti gli addetti sull’attacco al fuoco","effect":"Esodo e controllo area restano scoperti"}]'::jsonb,'{"questions":["Chi controlla l’esodo?","Quando usare un mezzo idrico se previsto e sicuro?","Come eviti di perdere il coordinamento?"]}'::jsonb,'[{"asset":"idea-fire-passive.svg"},{"asset":"idea-fire-response.svg"},{"asset":"idea-evac-public.svg"}]'::jsonb,'[{"kind":"reference","title":"Vigili del Fuoco - materiale addetti antincendio","url":"https://www.vigilfuoco.it/comando-vvf-rimini/formazione-abilitazione-e-aggiornamento-addetti-antincendio"}]'::jsonb,'[{"authority":"Corpo Nazionale Vigili del Fuoco","url":"https://www.vigilfuoco.it/comando-vvf-rimini/formazione-abilitazione-e-aggiornamento-addetti-antincendio"}]'::jsonb),
('v22:fire-l3','Antincendio L3: evento complesso e decisione di disimpegno','tabletop','addetto antincendio L3','L’evento coinvolge più aree, l’evoluzione non è immediatamente leggibile e le squadre interne devono mantenere coordinamento con l’esodo e l’arrivo dei soccorsi.','Definisci comando, comunicazioni, aree sicure, limiti dell’intervento interno e informazioni da consegnare ai Vigili del Fuoco.','[{"choice":"Mantengo un quadro comune, limiti di intervento e disimpegno anticipato se le condizioni superano la capacità interna","effect":"Squadra preservata e informazioni utili ai soccorsi"},{"choice":"Proseguo finché esiste una possibilità di contenimento","effect":"Esposizione crescente e perdita del margine di sicurezza"}]'::jsonb,'{"questions":["Quali indicatori impongono disimpegno?","Quali informazioni servono ai soccorritori?","Come eviti squadre non tracciate?"]}'::jsonb,'[{"asset":"idea-fire-response.svg"},{"asset":"idea-emergency-steps.svg"},{"asset":"procedura-operativa-5-fasi.svg"}]'::jsonb,'[{"kind":"reference","title":"Vigili del Fuoco - formazione antincendio","url":"https://www.vigilfuoco.it/comando-vvf-rimini/formazione-abilitazione-e-aggiornamento-addetti-antincendio"}]'::jsonb,'[{"authority":"Corpo Nazionale Vigili del Fuoco","url":"https://www.vigilfuoco.it/comando-vvf-rimini/formazione-abilitazione-e-aggiornamento-addetti-antincendio"}]'::jsonb),
('v22:first-aid-bc','Primo soccorso B/C: malore, trauma ed emorragia','decision','addetto primo soccorso gruppi B/C','Durante un turno una persona cade dopo un malore e presenta una ferita sanguinante.','Metti in sicurezza la scena, valuta priorità, attiva il sistema di emergenza e applica solo le manovre apprese, preparando l’handover.','[{"choice":"Gestisco prima sicurezza e funzioni vitali, poi il trauma secondo addestramento","effect":"Priorità corrette"},{"choice":"Mi concentro subito sulla ferita visibile","effect":"Possibile perdita di priorità clinica"}]'::jsonb,'{"questions":["Qual è la prima priorità?","Quali informazioni dai al 112/118?","Che cosa non devi improvvisare?"]}'::jsonb,'[{"asset":"idea-emergency-steps.svg"},{"asset":"stop-segnala-ripristina.svg"}]'::jsonb,'[{"kind":"video","title":"Croce Rossa Italiana - Il primo soccorso salva la vita","url":"https://www.youtube.com/watch?v=J0iegcSFowI"},{"kind":"reference","title":"INAIL - Primo soccorso nei luoghi di lavoro","url":"https://www.inail.it/portale/it/inail-comunica/news/notizia.2018.10.primo-soccorso-nei-luoghi-di-lavoro-online-un-nuovo-manuale-inail.html"}]'::jsonb,'[{"authority":"Croce Rossa Italiana","url":"https://www.youtube.com/watch?v=J0iegcSFowI"},{"authority":"INAIL","url":"https://www.inail.it/portale/it/inail-comunica/news/notizia.2018.10.primo-soccorso-nei-luoghi-di-lavoro-online-un-nuovo-manuale-inail.html"}]'::jsonb),
('v22:first-aid-a','Primo soccorso A: evento ad alta energia e più rischi','tabletop','addetto primo soccorso gruppo A','Un infortunio in area produttiva combina trauma importante e una possibile fonte di pericolo ancora attiva.','Organizza sicurezza scena, chiamata precoce, priorità, collaborazione tra addetti e accesso dei soccorsi senza eseguire manovre oltre la formazione.','[{"choice":"Blocchiamo l’esposizione, assegniamo ruoli e prepariamo accesso/handover","effect":"Soccorso organizzato"},{"choice":"Più persone intervengono contemporaneamente sulla vittima","effect":"Confusione e possibile seconda esposizione"}]'::jsonb,'{"questions":["Chi mette in sicurezza l’area?","Come distribuisci i ruoli?","Quali informazioni tecniche sono utili ai soccorsi?"]}'::jsonb,'[{"asset":"idea-emergency-steps.svg"},{"asset":"idea-safety-system.svg"}]'::jsonb,'[{"kind":"video","title":"Croce Rossa Italiana - Il primo soccorso salva la vita","url":"https://www.youtube.com/watch?v=J0iegcSFowI"},{"kind":"reference","title":"INAIL - Primo soccorso nei luoghi di lavoro","url":"https://www.inail.it/portale/it/inail-comunica/news/notizia.2018.10.primo-soccorso-nei-luoghi-di-lavoro-online-un-nuovo-manuale-inail.html"}]'::jsonb,'[{"authority":"Croce Rossa Italiana","url":"https://www.youtube.com/watch?v=J0iegcSFowI"},{"authority":"INAIL","url":"https://www.inail.it/portale/it/inail-comunica/news/notizia.2018.10.primo-soccorso-nei-luoghi-di-lavoro-online-un-nuovo-manuale-inail.html"}]'::jsonb),
('v22:evacuation-blocked-route','Evacuazione: via principale bloccata','tabletop','addetti emergenza/lavoratori','Durante il drill la via normalmente usata diventa improvvisamente indisponibile.','Riorganizza flusso, comunicazione, assistenza e conteggio usando il piano reale senza creare un controflusso.','[{"choice":"Attivo la via alternativa prevista e comunico il cambio ai punti chiave","effect":"Flusso coerente"},{"choice":"Faccio decidere autonomamente alle persone la via più vicina","effect":"Possibili controflussi e dispersione"}]'::jsonb,'{"questions":["Chi deve conoscere subito il cambio?","Come eviti il rientro?","Come gestisci il conteggio se i gruppi arrivano da vie diverse?"]}'::jsonb,'[{"asset":"idea-evac-public.svg"},{"asset":"idea-emergency-steps.svg"}]'::jsonb,'[{"kind":"video_hub","title":"Napo - emergenze e comportamento sicuro","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"}]'::jsonb)
on conflict(stable_key) do update set title=excluded.title,scenario_type=excluded.scenario_type,role_focus=excluded.role_focus,intro=excluded.intro,prompt=excluded.prompt,decisions=excluded.decisions,debrief=excluded.debrief,visuals=excluded.visuals,media=excluded.media,sources=excluded.sources,active=true,updated_at=now();

insert into public.practice_labs_v22(stable_key,title,lab_type,objective,briefing,steps,checklist,critical_errors,stop_conditions,media,sources,requires_physical_validation) values
('v22:fire-l1-lab','Antincendio L1: estintore e limite di intervento','physical','Riconoscere il mezzo, assumere posizione sicura ed eseguire la sequenza su focolaio didattico controllato.','La prova si svolge con istruttore e attrezzatura idonea; il digitale prepara ma non valida la manualità.','["riconosci classe/pericolo","scegli mezzo previsto","controlla via di fuga","allerta","prepara estintore","esegui tecnica sotto istruttore","arretra e sorveglia","debriefing"]'::jsonb,'["mezzo","via di fuga","distanza","tecnica","stop","sorveglianza"]'::jsonb,'["intervenire senza allarme","mettersi tra fuoco e uscita","avvicinarsi troppo","continuare quando il fuoco cresce"]'::jsonb,'["fumo/calore crescenti","via di fuga compromessa","mezzo non idoneo"]'::jsonb,'[{"kind":"reference","title":"Vigili del Fuoco - materiale addetti antincendio","url":"https://www.vigilfuoco.it/comando-vvf-rimini/formazione-abilitazione-e-aggiornamento-addetti-antincendio"}]'::jsonb,'[{"authority":"Corpo Nazionale Vigili del Fuoco","url":"https://www.vigilfuoco.it/comando-vvf-rimini/formazione-abilitazione-e-aggiornamento-addetti-antincendio"}]'::jsonb,true),
('v22:fire-l2-lab','Antincendio L2: squadra, estintore e mezzo idrico previsto','physical','Allenare coordinamento tra addetti, uso dei mezzi previsti e protezione dell’esodo.','Il docente assegna ruoli e introduce un cambio di scenario durante la prova.','["briefing squadra","allarme/esodo","ricognizione sicura","scelta mezzo","uso estintore","predisposizione naspo/idrante se previsto","comunicazione cambio condizioni","disimpegno","sorveglianza"]'::jsonb,'["ruoli","allarme","esodo","mezzi","comunicazione","disimpegno","ripristino"]'::jsonb,'["tutti sul focolaio","linea idrica senza coordinamento","via di fuga non mantenuta","nessun controllo dell’area"]'::jsonb,'["fumo non gestibile","comunicazione persa","esodo compromesso","condizioni oltre addestramento"]'::jsonb,'[{"kind":"reference","title":"Vigili del Fuoco - formazione addetti antincendio","url":"https://www.vigilfuoco.it/comando-vvf-rimini/formazione-abilitazione-e-aggiornamento-addetti-antincendio"}]'::jsonb,'[{"authority":"Corpo Nazionale Vigili del Fuoco","url":"https://www.vigilfuoco.it/comando-vvf-rimini/formazione-abilitazione-e-aggiornamento-addetti-antincendio"}]'::jsonb,true),
('v22:fire-l3-lab','Antincendio L3: comando, squadre e disimpegno','physical','Allenare organizzazione e limiti dell’intervento interno in uno scenario complesso simulato.','Non si ricreano condizioni realmente pericolose: complessità, fumo e propagazione possono essere simulate/tabletop e le manovre sui mezzi si svolgono separatamente in sicurezza.','["assegna comando/ruoli","mappa persone e aree","attiva esodo","predisponi mezzi","esegui manovre pratiche previste","introduci perdita di una via","decidi disimpegno","prepara handover Vigili del Fuoco","debriefing"]'::jsonb,'["comando","tracciamento squadra","esodo","mezzi","comunicazioni","disimpegno","handover"]'::jsonb,'["squadra non tracciata","nessun limite di intervento","informazioni non condivise","rientro non autorizzato"]'::jsonb,'["scenario supera capacità interna","comunicazione non affidabile","via di fuga non garantita"]'::jsonb,'[{"kind":"reference","title":"Vigili del Fuoco - formazione antincendio","url":"https://www.vigilfuoco.it/comando-vvf-rimini/formazione-abilitazione-e-aggiornamento-addetti-antincendio"}]'::jsonb,'[{"authority":"Corpo Nazionale Vigili del Fuoco","url":"https://www.vigilfuoco.it/comando-vvf-rimini/formazione-abilitazione-e-aggiornamento-addetti-antincendio"}]'::jsonb,true),
('v22:first-aid-bc-lab','Primo soccorso B/C: RCP/DAE, emorragia e trauma','physical','Mantenere abilità essenziali con manichino e scenari brevi, privilegiando sequenza e decisione.','Il formatore osserva e corregge; non si simulano procedure invasive né uso di farmaci.','["sicurezza scena","valutazione iniziale","chiamata soccorsi","RCP su manichino secondo training","DAE didattico se previsto","gestione emorragia simulata","posizione/trauma secondo addestramento","handover"]'::jsonb,'["scena","chiamata","sequenza RCP","DAE","emorragia","trauma","handover"]'::jsonb,'["ritardare allarme","interrompere spesso la sequenza","toccare la persona durante analisi/scarica DAE","improvvisare farmaci"]'::jsonb,'["scena non sicura","situazione oltre competenze","presidio non funzionante"]'::jsonb,'[{"kind":"video","title":"Croce Rossa Italiana - Il primo soccorso salva la vita","url":"https://www.youtube.com/watch?v=J0iegcSFowI"}]'::jsonb,'[{"authority":"Croce Rossa Italiana","url":"https://www.youtube.com/watch?v=J0iegcSFowI"},{"authority":"INAIL","url":"https://www.inail.it/portale/it/inail-comunica/news/notizia.2018.10.primo-soccorso-nei-luoghi-di-lavoro-online-un-nuovo-manuale-inail.html"}]'::jsonb,true),
('v22:first-aid-a-lab','Primo soccorso A: scenario complesso multi-addetto','physical','Allenare priorità, lavoro in squadra, RCP/DAE e gestione di trauma/emorragia in un contesto produttivo complesso.','Usare manichino e materiali simulati; nessuna esposizione reale a energia, sostanze o pericoli.','["messa in sicurezza simulata","assegna ruoli","valutazione iniziale","chiamata precoce","RCP/DAE su manichino","controllo emorragia simulato","gestione trauma secondo addestramento","accesso mezzi di soccorso","handover strutturato"]'::jsonb,'["scena","ruoli","chiamata","RCP/DAE","emorragia","trauma","accesso soccorsi","handover"]'::jsonb,'["più soccorritori senza coordinamento","entrare in area non resa sicura","spostare traumatizzato senza motivo previsto","diagnosticare oltre competenze"]'::jsonb,'["fonte di pericolo non isolata","scenario oltre competenza","mancanza DPI/presidi necessari"]'::jsonb,'[{"kind":"video","title":"Croce Rossa Italiana - Il primo soccorso salva la vita","url":"https://www.youtube.com/watch?v=J0iegcSFowI"}]'::jsonb,'[{"authority":"Croce Rossa Italiana","url":"https://www.youtube.com/watch?v=J0iegcSFowI"},{"authority":"INAIL","url":"https://www.inail.it/portale/it/inail-comunica/news/notizia.2018.10.primo-soccorso-nei-luoghi-di-lavoro-online-un-nuovo-manuale-inail.html"}]'::jsonb,true),
('v22:evacuation-specific-lab','Drill evacuazione con imprevisto e debriefing','physical','Verificare non solo l’uscita, ma la capacità del sistema di adattarsi a una via indisponibile senza perdere persone o comunicazioni.','Il docente/responsabile introduce un imprevisto simulato già sicuro e controllato.','["briefing osservatori","allarme","avvio evacuazione","blocco simulato di una via","deviazione su alternativa","assistenza persone fragili secondo piano","punto raccolta","conteggio","debriefing con azioni correttive"]'::jsonb,'["tempi","comunicazione","alternative","assistenza","conteggio","azioni correttive"]'::jsonb,'["controflusso","rientro","persone non conteggiate","imprevisto non comunicato"]'::jsonb,'["emergenza reale","via alternativa non sicura"]'::jsonb,'[{"kind":"video_hub","title":"Napo - emergenze","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"}]'::jsonb,true)
on conflict(stable_key) do update set title=excluded.title,lab_type=excluded.lab_type,objective=excluded.objective,briefing=excluded.briefing,steps=excluded.steps,checklist=excluded.checklist,critical_errors=excluded.critical_errors,stop_conditions=excluded.stop_conditions,media=excluded.media,sources=excluded.sources,requires_physical_validation=excluded.requires_physical_validation,active=true,updated_at=now();

